package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

var reader *bufio.Reader
var writer *bufio.Writer

var currentLineTokens []string

func readAndSplitLine() []string {
	line, _ := reader.ReadString('\n')
	line = strings.TrimRight(line, "\r\n")
	fields := strings.FieldsFunc(line, func(r rune) bool {
		return r == ' ' || r == '\t'
	})
	return fields
}

func ReadToken() string {
	for len(currentLineTokens) == 0 {
		currentLineTokens = readAndSplitLine()
	}
	token := currentLineTokens[0]
	currentLineTokens = currentLineTokens[1:]
	return token
}

func ReadInt() int {
	v, _ := strconv.Atoi(ReadToken())
	return v
}

func ReadLong() int64 {
	v, _ := strconv.ParseInt(ReadToken(), 10, 64)
	return v
}

func Write(args ...interface{}) {
	strs := make([]string, len(args))
	for i, a := range args {
		strs[i] = fmt.Sprintf("%v", a)
	}
	writer.WriteString(strings.Join(strs, " "))
	writer.WriteString("\n")
}

func Solve() {
	n := ReadInt()
	m := ReadInt()

	if m == 1 {
		Write(n - 1)
	} else {
		Write(int64(n) * int64(m-1))
	}
}

func main() {
	reader = bufio.NewReader(os.Stdin)
	writer = bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	Solve()
}
